import Schema from '@deepseek-ai/schemastery'
import { DEFAULT_SCAN_DEPTH, DEFAULT_SCAN_FILES, isUnsafeRoot } from './util/fs.js'
import { indexDocTool } from './tools/index-doc.js'
import { indexRepoTool, indexRepository } from './tools/index-repo.js'
import { queryMemoryTool } from './tools/query-memory.js'
import { rememberTool } from './tools/remember.js'
import { forgetTool } from './tools/forget.js'
import { watchRepoTool } from './tools/watch-repo.js'
import { statsTool } from './tools/stats.js'
import { WatchManager } from './watch.js'
import { setupLazyIndexing } from './lazy.js'
import { initTypeScript } from './enhancer.js'
import { setupTaskbridge } from './setup/taskbridge.js'
import { listTasksTool, selectTaskTool, archiveTaskTool, showTaskPanelTool } from './tools/task-tools.js'
import { lessonTool } from './tools/lesson-tools.js'
import { installAutoInject } from './auto-inject.js'
import { rememberRoute } from './llm-route.js'
import { workflowCommandDefinition } from './commands/workflow.js'

export const name = 'dsh-project-memory'
export const inject = ['llm', 'tools']

export const Config = Schema.object({
  memoryDir: Schema.string().default('.dsh-project-memory'),
  chunkChars: Schema.number().default(3000),
  maxChunksPerFile: Schema.number().default(40),
  // 单文件内存闸门，不是磁盘设置：索引一个文件要先把它整个物化，峰值随文件大小线性走。
  // 实测边际系数（峰值 RSS / 磁盘 MB，见 bench/file-peak.mjs 与 README「单文件内存预算」）：
  // 典型源码 ~10×、符号密集代码 ~21×、文本型 PDF ~19×。10 把单文件增量压在 ~+300 MB。
  maxFileSizeMb: Schema.number().default(10),
  maxOutputChars: Schema.number().default(8000),
  maxPdfPages: Schema.number().default(1000),
  llmQueryExpansion: Schema.boolean().default(false),
  expansionCount: Schema.number().default(6),
  // 辅助 LLM 调用的路由覆写 —— **索引期零 LLM**，这里的路由只服务于召回期可选项
  // （llmQueryExpansion 查询扩展）与反思期（reflection.enabled）。
  // 未设置时：工具调用取当前会话 header 的 provider/model；后台路径取最近一次会话路由（request/header）。
  // 两者都拿不到时明确走回退并记录 degraded（不静默）。
  llm: Schema.object({
    provider: Schema.string(),
    model: Schema.string(),
  }).default({}),
  lazyIndexing: Schema.boolean().default(true),
  autoIndexOnFirstUse: Schema.boolean().default(false),
  watch: Schema.boolean().default(true),
  watchInterval: Schema.number().default(30),
  // 危险根护栏（issue #5）：家目录 / 文件系统根 / 系统目录 / 包管理器前缀（/opt/homebrew …）
  // 整体扫描会吃满内存，默认一律拒绝。懒索引、会话审计、任务桥在这类目录里始终零副作用；
  // `autoIndexOnFirstUse` 不在此列——本开关同样放行它。其余只放开**显式**带 root 的工具调用。
  allowUnsafeRoots: Schema.boolean().default(false),
  // 单次扫描上限。超过即截断（并跳过"删除本轮未见到条目"的清理，避免把没扫到的文件误删）。
  // **不可取消**：0 / 负数 / 非数值一律回落默认值（见 util/fs.js 的 scanLimits）。
  maxScanFiles: Schema.number().default(DEFAULT_SCAN_FILES),
  maxScanDepth: Schema.number().default(DEFAULT_SCAN_DEPTH),
  tsPath: Schema.string(),
  enableTypeScript: Schema.boolean().default(true),
  tasklist: Schema.object({
    enabled: Schema.boolean().default(true),
    // 任务成为会话绑定（select_task / /task switch）时，把任务步骤推成宿主 todo/write 快照
    syncHostOnAdopt: Schema.boolean().default(true),
  }).default({}),
  // v0.5 单一 insight 实体：分层去重/强化/提升/容量/归档
  insight: Schema.object({
    dedupOverlap: Schema.number().default(0.7),
    reinforceBand: Schema.number().default(0.65),
    // 向量带（需 leanvec；未装自动退化成上面的纯词法带）。下面四个键自 0.6.x 起就在
    // cfgInsight（src/insight-store.js）里读取、README 与 types.js 也写了，却一直没进
    // Schema。与 0.5.8 给 autoContext 补声明是同一类问题：未声明键在 schemastery 层会透传，
    // 但走 cordis.patch.yml 时能不能活到代码取决于宿主是否按「not a declared property」校验
    // ——无论哪种，文档里的旋钮与 Schema 已经不一致，等于半真半假。默认值以 cfgInsight 的
    // 兜底值为权威，这里只负责把键暴露出来。
    autoMergeCos: Schema.number().default(0.9),
    autoMergeMargin: Schema.number().default(0.05),
    hintCos: Schema.number().default(0.7),
    maxForgetMatches: Schema.number().default(10),
    maxProject: Schema.number().default(100),
    maxGlobalProcedures: Schema.number().default(200),
    promoteConfidence: Schema.number().default(0.7),
    globalPromoteTasks: Schema.number().default(3),
    decayDays: Schema.number().default(90),
    globalFile: Schema.string(),
  }).default({}),
  // 反思管线（召回期可选 LLM 消费点，默认关）。产出只写 task 级草稿。
  reflection: Schema.object({
    enabled: Schema.boolean().default(false),
    cooldownMs: Schema.number().default(1800000),
    maxLessonsPerReflect: Schema.number().default(3),
    maxDecisionsPerReflect: Schema.number().default(2),
  }).default({}),
  // PR 2：静默注入（entry 常驻块 + relevance 门控）。无项目 root 可解析时零副作用
  autoContext: Schema.object({
    enabled: Schema.boolean().default(true),
    entryOn: Schema.boolean().default(true),
    maxTokens: Schema.number().default(400),
    entryMaxInsights: Schema.number().default(6),
    // 提示通道的相对阈值（层内最高分的比例）——出厂判据
    signalMinRatio: Schema.number().default(0.5),
    // resident 任务卡最多显示几个「编辑中」文件
    editedMax: Schema.number().default(3),
    // 记忆根是"推定"的（会话工作目录，且该目录没有项目标记）时，首次注入前通告模型
    // 根在哪、怎么改。状态声明，只发一次、不占条目额度。
    rootNotice: Schema.boolean().default(true),
    // 模型自己维护清单且之后没有新人类消息时，不把任务卡回声给模型
    skipEchoSelfTodo: Schema.boolean().default(true),
    // ⚠️ 旧兼容闸门，**刻意不给默认值**：cfgEngine 以「relevanceMin 是否为 number」选分支，
    // 一旦有默认值就会永远走旧的绝对 overlap 判据——而它对长消息实测只有 0.014~0.057，
    // 必然过不了，相对阈值 signalMinRatio 就变成死代码。只有用户显式配置才保留旧行为。
    relevanceMin: Schema.number(),
    // 预算审计日志（stderr）**默认 off**：终端是用户可见面，而"预算挤掉低优先级条目"是
    // 正常降级、不是故障——默认打印会让一次 dsh web 启动刷出多行，用户的第一反应是卸载插件。
    // off（默认，永不打印）/ once（每个会话最多一行，首次出现丢弃时）/ all（丢弃组合每变化一次一行，作者排查）
    budgetLog: Schema.union(['off', 'once', 'all']).default('off'),
    // 同一条 insight 在本会话里重复注入的冷却（pre-step 步数）。0（默认）= 正文没变就不再注入：
    // 注入消息留在会话历史里（宿主只追加不压缩），整块重发只是重复占位。>0 用于外部裁剪历史的场景。
    reinjectItemsAfter: Schema.number().default(0),
    // --- 准入旋钮（0.5.8 起补声明）---
    // 下面这些键自 S2/S4 起就在 cfgEngine / cfgAudit 里生效、README 也一直写着，但**从未**在
    // Schema 里声明过：走 cordis.patch.yml 配它们会被宿主按「not a declared property」拒掉，
    // 等于文档里的旋钮是假的。默认值以 cfgEngine 的兜底值为准（那里是权威，这里只负责暴露）。
    gateCooldownSteps: Schema.number().default(2),
    // 这两个是**保险丝**不是节流阀：节流由 gateCooldownSteps 与单轮 maxTokens 负责。
    // 旧默认 12 / 4000 ≈ 11 条，实测真实日志里 11/81 个会话打满、打满后永久静默（1234 步失明）；
    // 实测最长会话用 35 条 / 8640 字符，故抬到 60 / 24000。显式配小值可复现旧行为。
    maxItemsPerSession: Schema.number().default(60),
    maxItemCharsPerSession: Schema.number().default(24000),
    hintMinCoverage: Schema.number().default(0.45),
    hintMinMatched: Schema.number().default(2),
    hintMinSupport: Schema.number().default(0.15),
    // 可选向量层（leanvec）：**不装就是纯词法**，装了也只改经验/洞察层的**排序**——
    // 闸门（覆盖率/共同词数）与返回条数都不变，doc/symbol 层完全不受影响。
    // `vectorDir` 刻意**不给默认值**（与 relevanceMin 同一套约定：有默认值会让"是否启用"永远为真）。
    // 解析顺序：本项显式路径 > 环境变量 DSH_LEANVEC_DIR > **可选依赖 `leanvec`**（装上即自动命中）。
    // 目录里需有 dist/leanvec.f32 与 dist/leanvec.tokenizer.json。
    // **填 `off` 可强制关闭**（连模型都不加载）：装了可选依赖之后仍有退回纯词法的开关。
    vectorDir: Schema.string(),
    // 融合权重 (1-α)·BM25归一 + α·余弦。实测**小 k** 上 α=0.5 最优（k=3 64% vs 58%、k=5 69% vs 67%，
    // α=0.75 时 k=5 到 72%），而 α=1（纯向量）明显更差（hit@10 53% vs 81%）——所以默认 0.5 不是 1。
    vectorAlpha: Schema.number().default(0.5),
    // legacy `trigger.scope` 的处置。默认 **ignore**：它的值由作者手写，几乎不可能落在
    // 自动派生的项目画像 tag 空间里（实测唯一一条带 scope 的条目因此永远无法命中），
    // 拿它当收窄条件只会判死条目。`readiness.js` 的注释一直写的是"默认忽略"，这里此前
    // 是 `'filter'` —— 注释与实现不一致，以注释为准。显式配 'filter' 可恢复旧语义。
    legacyScope: Schema.union(['filter', 'ignore']).default('ignore'),
    auditLog: Schema.boolean().default(true),
    auditMaxBytes: Schema.number().default(262144),
    // 影子记录（admission-shadow.jsonl）：**每步**一行，含全部候选的判据特征与场景。
    // 主审计只在真的注入时写，静默步零痕迹 → 无法离线重放"换个阈值会怎样"，也攒不出样本。
    // 只写盘、不进 prompt、不花 token，所以默认开。
    // 512KB 而不是 2MB：轮转只留 `.1` 一代，所以单项目日志的硬上限是
    // `2 × shadowMaxBytes + 2 × auditMaxBytes`（原 4.6MB）；512KB 下约 1.5MB。
    shadowLog: Schema.boolean().default(true),
    shadowMaxBytes: Schema.number().default(524288),
  }).default({}),
})

export function apply(ctx, config) {
  // Initialize TypeScript enhancer if enabled
  if (config.enableTypeScript !== false) {
    initTypeScript(config)
  }

  const watchManager = new WatchManager(ctx, config)
  if (config.watch) {
    watchManager.restorePersisted()
    ctx.effect(() => {
      watchManager.start(config.watchInterval * 1000)
      return () => watchManager.stop()
    })
  }

  if (config.lazyIndexing) {
    setupLazyIndexing(ctx, config, watchManager)
  }

  // TaskBridge：任务实体 + 宿主 todo 同步
  setupTaskbridge(ctx, config)
  // 跟踪会话路由（request/header 事件），为无会话上下文的召回期可选 LLM（查询扩展 / 反思）兜底
  ctx.on('session/event', (session, event) => {
    if (event?.type === 'request/header') rememberRoute(session)
    // 会话活跃信号：有人正在跑回合时把 watch 轮询压到最低，回合结束立刻补扫一次（见 watch.js）。
    // 这是"轮询只在空闲时发生"的落点 —— 交互期间把 I/O 全让给模型，停下那一刻才整理索引。
    const key = session?.id ?? 'unknown'
    if (event?.type === 'turn/start' || event?.type === 'step/start') watchManager.setSessionActive(key, true)
    else if (event?.type === 'turn/end') watchManager.setSessionActive(key, false)
  })
  // 会话被销毁时也要摘掉活跃标记：否则一个没有正常 turn/end 的会话会把轮询**永久**压在兜底节拍
  // （不会卡死，但"空闲时高速刷新"再也不会回来）。
  ctx.on('session/disposed', (session) => {
    watchManager.setSessionActive(session?.id ?? 'unknown', false)
  })
  ctx.tools.register(listTasksTool(config))
  ctx.tools.register(selectTaskTool(config, { llm: ctx.llm, ctx }))
  ctx.tools.register(archiveTaskTool(config, { llm: ctx.llm, ctx }))
  ctx.tools.register(showTaskPanelTool(config))

  // /tasks：唯一的用户命令（合并自原 /tasks、/task、/insight —— 宿主命令只要注册就会
  // 出现在 `/` 菜单的「指令」组里且无法隐藏，三条命令就是三行去不掉的原始行）。
  // 切换/归档/审核等动作作为子动词，由面板按钮经 remote.commands.execute 驱动。
  try {
    ctx.inject(['commands'], (commandsCtx) => {
      commandsCtx.commands.register(workflowCommandDefinition(config, ctx))
    })
  } catch (err) {
    console.error(`[dsh-project-memory] /tasks registration skipped: ${err.message}`)
  }

  ctx.tools.register(indexDocTool(ctx, config))
  ctx.tools.register(indexRepoTool(ctx, config))
  ctx.tools.register(queryMemoryTool(ctx, config))
  ctx.tools.register(rememberTool(config))
  ctx.tools.register(forgetTool(config))
  ctx.tools.register(lessonTool(config))
  ctx.tools.register(watchRepoTool(watchManager, config))
  ctx.tools.register(statsTool(config))

  // PR 2：注册 agent/pre-step 监听，向每步请求的 enter 决策追加记忆消息（默认开；
  // 任何异常/无会话 cwd → 交回默认决策，零副作用）
  installAutoInject(ctx, config)

  if (config.autoIndexOnFirstUse) {
    // effect 回调必须同步并返回 disposer；异步体独立执行，用 cancelled 标志避免卸载后再写日志
    ctx.effect(() => {
      let cancelled = false
      const run = async () => {
        const root = process.cwd()
        // 全量索引 cwd 是显式开启的行为，但"cwd 是家目录"几乎总是误用：拒绝并说明，
        // 而不是替用户把整棵树扫一遍（旧实现直接 indexRepository(ctx, config, cwd)，
        // 没有任何护栏——这正是 issue #5 里最直接的 OOM 入口）。
        if (isUnsafeRoot(root) && config.allowUnsafeRoots !== true) {
          if (!cancelled) {
            console.error(
              `[dsh-project-memory] autoIndexOnFirstUse skipped: cwd ${root} is not a project root ` +
                '(home / system / package-manager prefix). Start dsh inside a project directory, ' +
                'or set allowUnsafeRoots: true to override.',
            )
          }
          return
        }
        try {
          watchManager.addRoot(root)
          const report = await indexRepository(ctx, config, root, { allowUnsafe: config.allowUnsafeRoots === true })
          if (!cancelled) console.log(`[dsh-project-memory] ${report}`)
        } catch (err) {
          if (!cancelled) console.error(`[dsh-project-memory] auto-index failed for ${root}: ${err.message}`)
        }
      }
      run()
      return () => {
        cancelled = true
      }
    })
  }
}

files.src/setup/taskbridge.js:
// TaskBridge 运行时：监听会话事件，把宿主 todo/工具调用同步进任务实体。
// 事实依据：dsh session/event 签名 (session, event)；todo/write data.todos；
// tool/call data.arguments 为 JSON 字符串；fs 工具名 read/write/edit/read_image，参数 file_path。
import path from 'node:path'
import { createHash, randomUUID } from 'node:crypto'
import { memoryRootFor, resolveProjectMemoryRoot } from '../util/fs.js'
import { sessionWorkingDir } from '../util/session-dir.js'
import { ProjectMemoryStore } from '../store.js'
import { stepContent, stepStatus } from '../util/task-view.js'

const FS_FILE_TOOLS = new Set(['read', 'write', 'edit', 'read_image'])
const WRITE_TOOLS = new Set(['write', 'edit']) // 编辑/写入 = 高热点
const READ_TOOLS = new Set(['read', 'read_image'])
const MAX_FILES_PER_TASK = 100
const TITLE_MAX = 24

export function hash8(text) {
  return createHash('sha256').update(String(text)).digest('hex').slice(0, 8)
}

export function slugifyTitle(text) {
  return String(text || '')
    .toLowerCase()
    .replace(/[^\w\u4e00-\u9fff]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, TITLE_MAX)
}

export function genTaskId(projectRoot, title) {
  const slug = slugifyTitle(title) || 'task'
  // 毫秒不是唯一性保证：两个会话在同一毫秒建同名任务会拿到同一个 id，
  // addTask 变成"同一 id 两次"，两个会话的绑定互相串台。补 6 位随机后缀。
  return `tsk_${hash8(projectRoot)}_${slug}_${Date.now().toString(36)}_${randomUUID().slice(0, 6)}`
}

/** 会话根不可用时统一的用户提示（/tasks、/task、/insight 共用）。 */
export const NO_PROJECT_ROOT_NOTE =
  '当前工作目录不是项目根（是家目录/系统目录且没有项目标记），项目记忆与任务清单已停用；请在项目目录内启动 dsh。'

/**
 * 项目根推导：与全插件同一套策略（util/fs.js 的 `resolveProjectMemoryRoot`）——
 * 最近的 VCS/清单标记优先；标记缺失但 cwd 本身是安全目录时退回 cwd（任务清单按
 * "会话工作目录"归属，没有标记的普通目录也要能用）；cwd 是家目录/系统/包管理器前缀
 * 且上方没有标记时返回 null。
 */
export function projectRootFor(cwd) {
  return resolveProjectMemoryRoot(cwd || process.cwd())
}

/** 没有可用项目根时返回 `{ root: null, store: null }`，调用方据此整段跳过。 */
export function taskStoreFor(cwd, config) {
  const root = projectRootFor(cwd)
  if (!root) return { root: null, store: null }
  return { root, store: new ProjectMemoryStore(memoryRootFor(root, config.memoryDir)).load() }
}

/** 把工具参数里的文件路径归一化为项目相对路径；项目外返回 null。 */
export function normalizeRelFile(root, file) {
  if (typeof file !== 'string' || !file) return null
  const abs = path.isAbsolute(file) ? file : path.resolve(root, file)
  const rel = path.relative(root, abs)
  if (!rel || rel.startsWith('..') || path.isAbsolute(rel)) return null
  return rel.split(path.sep).join('/')
}

/** content 可能是字符串或 ContentBlock[]，统一取首段文本。 */
export function firstTextOf(content) {
  if (typeof content === 'string') return content
  if (Array.isArray(content)) {
    for (const b of content) {
      if (b && typeof b.text === 'string' && b.text.trim()) return b.text
    }
  }
  return ''
}

/**
 * 反向接管：任务成为某会话绑定后，把任务步骤推成宿主 todo/write 快照，
 * 让 dsh 渲染的任务清单（UI/投影）变成我们这套任务的步骤。
 * 规则：任务没有步骤时不推（避免误清模型手头正在用的宿主清单）。
 * @returns {boolean} 是否实际推送
 */
export function adoptStepsToSession(session, task) {
  if (!session || typeof session.append !== 'function') return false
  const steps = Array.isArray(task?.steps) ? task.steps : null
  if (!steps || steps.length === 0) return false
  const todos = steps.map((s) => ({ content: String(stepContent(s)), status: stepStatus(s) }))
  session.append('todo/write', { todos })
  return true
}

/** 是否开启“任务接管时同步宿主清单”（config.tasklist.syncHostOnAdopt 默认 true）。 */
export function shouldAdoptToHost(config) {
  return config?.tasklist?.syncHostOnAdopt !== false
}

/**
 * 子代理会话判定：宿主 SessionHeader 对 in-process 子代理恒定写入
 * `origin: 'subagent'` 与 `delegationDepth`（parent depth + 1）。
 * 刻意不看 parentSession —— 那是 fork/seed 血缘，用户 fork 出来的顶层会话同样带它。
 */
export function isSubagentSession(session) {
  const header = session?.header
  if (!header) return false
  if (header.origin === 'subagent') return true
  return typeof header.delegationDepth === 'number' && header.delegationDepth > 0
}

/**
 * 标题优先级：清单首条 > 首条真人消息 > 'Untitled Task'（0.5.3 反转前两者）。
 * 真人消息只在清单没有可用文本时兜底：重启后 meta.firstHuman 是重启后的第一条消息
 * （常常只是半途闲聊，如"刚刚你卡死了，注意点"），拿它命名会把任务带偏。
 */
function pickTitle(meta, todos) {
  const firstTodo = todos?.[0]?.content
  if (typeof firstTodo === 'string' && firstTodo.trim()) return firstTodo.trim().slice(0, 48)
  const firstHuman = meta?.firstHuman?.trim()
  if (firstHuman) {
    // 用户消息常带指令前缀（"用 todo_write 规划：…"），优先取最后一个"："后的任务段
    const idx = Math.max(firstHuman.lastIndexOf('：'), firstHuman.lastIndexOf(':'))
    const seg = idx >= 0 ? firstHuman.slice(idx + 1).trim() : ''
    if (seg.length >= 2 && seg.length <= 48) return seg
    return firstHuman.slice(0, 48)
  }
  return 'Untitled Task'
}

/**
 * 热点排序：写过(编辑)的文件永远排前；同是写过按 lastWriteAt 倒序；
 * 纯读文件按 lastReadAt 倒序排在写区之后（任何读取都不会越过写过文件）。
 */
export function hotSortFiles(files, meta) {
  const m = meta || {}
  return (files || []).slice().sort((a, b) => {
    const A = m[a]
    const B = m[b]
    const aw = A && A.lastWriteAt ? 1 : 0
    const bw = B && B.lastWriteAt ? 1 : 0
    if (aw !== bw) return bw - aw
    if (aw) return String(B.lastWriteAt).localeCompare(String(A.lastWriteAt))
    return String(B.lastReadAt || '').localeCompare(String(A.lastReadAt || ''))
  })
}

/** 触碰文件后更新元数据并重排 task.files（写 vs 读分别记时间/次数）。 */
export function touchTaskFile(task, rel, kind, now) {
  task.fileMeta = task.fileMeta || {}
  if (!task.files.includes(rel)) task.files.push(rel)
  const m = task.fileMeta[rel] || {}
  m.n = (m.n || 0) + 1 // 兼容旧字段：读+写总数（保留，避免老任务语义漂移）
  // 读/写分计数（先只采集，不消费 —— 排序与注入仍只用 lastWriteAt/lastReadAt）
  if (kind === 'write') {
    m.writes = (m.writes || 0) + 1
    m.lastWriteAt = now
  } else if (kind === 'read') {
    m.reads = (m.reads || 0) + 1
  }
  m.lastReadAt = now
  task.fileMeta[rel] = m
  task.files = hotSortFiles(task.files, task.fileMeta)
  // 超限丢最冷的：列表已按热度降序，末尾即最冷。旧代码在**重排前** shift()，
  // 而那时 files 本身就是热序，shift 恰好把最热的那个文件（刚写的）丢掉、留下最冷的。
  while (task.files.length > MAX_FILES_PER_TASK) {
    const dropped = task.files.pop()
    delete task.fileMeta[dropped]
  }
}

/**
 * 单条会话事件处理（导出便于测试）：user/message 记首条真人文本并刷新 lastHumanAt；
 * todo/write → 已绑定则覆盖 steps，未绑定则自动新建任务并绑定（子代理会话除外，
 * 由 isSubagentSession 判定）；tool/call（fs 工具）→ 绑定任务 files 并集。
 */
export function onSessionEvent(config, session, event, meta, ctx) {
  const sessionId = session?.id
  const type = event?.type
  if (!sessionId || !type) return
  const now = new Date().toISOString()
  // 任务清单按「会话当前工作目录」归属：0.2.1+ 该目录由 workingDirectory 投影决定
  // （cd 后会变），老宿主回退 header.cwd。`ctx` 只在宿主装配路径上给得到；测试与
  // 老调用方不给也能跑（回退 header.cwd）。
  const cwd = sessionWorkingDir(session, { ctx })

  // 人类消息：记首条真人文本 + 若已绑定任务则刷新 lastHumanAt（供“模型自维护不回声任务卡”判断）
  if (type === 'user/message') {
    if (event.data?.source?.kind === 'user') {
      const text = firstTextOf(event.data?.content)
      const m = meta.get(sessionId) || {}
      if (!m.firstHuman && text) m.firstHuman = text
      m.lastHumanAt = now
      meta.set(sessionId, m)
      try {
        const { store } = taskStoreFor(cwd, config)
        if (!store) return
        store.commit((s) => {
          const tid = s.getBoundTaskId(sessionId)
          const task = tid ? s.getTask(tid) : null
          if (task && !task.archived) {
            task.lastHumanAt = now
            task.updatedAt = now
            // 直接改了 task 内容就必须走标脏入口：只手置 _dirtyTasks 会漏掉驻留估算的新版本维。
            s.markTasksDirty()
          }
        })
      } catch {
        /* 人类消息戳记失败不影响主流程 */
      }
    }
    return
  }

  const { root, store } = taskStoreFor(cwd, config)
  // 没有项目根（家目录/系统目录会话）：不建档、不记文件、不落任何盘。
  if (!store) return

  if (type === 'todo/write') {
    const todos = event.data?.todos
    if (!Array.isArray(todos)) return
    store.commit((s) => {
      let task = s.getBoundTaskId(sessionId) ? s.getTask(s.getBoundTaskId(sessionId)) : null
      if (!task || task.archived) {
        // 空写 = 清空清单：不自动建档（避免"未绑定会话清空 todo"误建垃圾任务）
        if (todos.length === 0) return
        // 子代理会话不建档：否则每个子代理都铸一条项目任务（子代理任务融合另行设计）
        if (isSubagentSession(session)) return
        const title = pickTitle(meta.get(sessionId), todos)
        task = {
          id: genTaskId(root, title),
          projectHash: hash8(root),
          projectRoot: root,
          title,
          steps: null,
          files: [],
          fileMeta: {},
          archived: false,
          lastSessionId: sessionId,
          createdAt: now,
          updatedAt: now,
          lastActiveAt: now,
        }
        s.addTask(task)
        s.setBinding(sessionId, task.id)
      }
      task.steps = todos
      task.lastTodoAt = now // 模型/todo 最近一次自维护时刻
      task.updatedAt = now
      task.lastActiveAt = now
      task.lastSessionId = sessionId
      s.markTasksDirty()
    })
    return
  }

  if (type === 'tool/call') {
    const taskId = store.getBoundTaskId(sessionId)
    if (!taskId) return
    const data = event.data
    if (!data?.name || !FS_FILE_TOOLS.has(data.name)) return
    let args
    try {
      args = typeof data.arguments === 'string' ? JSON.parse(data.arguments) : data.arguments
    } catch {
      return
    }
    const raw = typeof args?.file_path === 'string' ? args.file_path : null
    if (!raw) return
    const rel = normalizeRelFile(root, raw)
    if (!rel) return
    const kind = WRITE_TOOLS.has(data.name) ? 'write' : READ_TOOLS.has(data.name) ? 'read' : null
    if (!kind) return
    store.commit((s) => {
      const task = s.getTask(taskId)
      if (!task || task.archived) return
      touchTaskFile(task, rel, kind, now)
      task.lastActiveAt = now
      s.markTasksDirty()
    })
  }
}

/** 插件接线：订阅 session/event；卸载时清会话元数据。 */
export function setupTaskbridge(ctx, config) {
  if (config.tasklist?.enabled === false) return
  const meta = new Map()
  ctx.on('session/event', (session, event) => {
    try {
      onSessionEvent(config, session, event, meta, ctx)
    } catch (err) {
      console.error('[dsh-project-memory] taskbridge:', err?.message)
    }
  })
  ctx.effect(() => () => meta.clear())
}

